node -e "
const initSqlJs = require('sql.js');
const fs = require('fs');

async function main() {
  const SQL = await initSqlJs();
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);

  // Search everywhere for 'TechPhone'
  const tables = db.exec(\"SELECT name FROM sqlite_master WHERE type='table'\");
  for (const tbl of tables[0].values) {
    const name = tbl[0];
    try {
      // Get all text columns
      const info = db.exec('PRAGMA table_info(' + name + ')');
      if (!info.length) continue;
      const textCols = info[0].values.filter(r => r[2] === 'TEXT').map(r => r[1]);
      for (const col of textCols) {
        try {
          const res = db.exec('SELECT * FROM ' + name + ' WHERE ' + col + ' LIKE \"%TechPhone%\"');
          if (res.length && res[0].values.length) {
            console.log('Found TechPhone in', name + '.' + col + ':', JSON.stringify(res[0].values));
          }
        } catch(e) {}
      }
    } catch(e) {}
  }
  console.log('Search complete.');
}
main().catch(console.error);
"

